Definition op_xok (xenc : Z) : Prop := exists x, 0 <= x < 2 ^ 32 /\ xenc = LbB_DiagStmt.sx32 x.

Lemma zext32_sx32 : forall x, 0 <= x < 2 ^ 32 ->
